function quickSell(gid){const buyer=state.customers.find(c=>c.city===state.city&&c.good===gid);if(!buyer){notify('No local buyer wants that good right now. Meet buyers in a neighborhood scene.');go('market');return}sellToCustomer(buyer.id)}
function playStoryPrompt(){if(state.dead){notify('Start a new chapter before choosing another action.');return}const field=$('#storyPrompt'),result=$('#storyPromptResult'),prompt=field.value.trim().toLowerCase();if(!prompt){result.textContent='Describe a small, everyday intention first.';return}let outcome,kind;if(/\b(rest|sleep|recover|take it easy|unwind|relax|check in|wellbeing)\b/.test(prompt)){const gain=Math.min(8,100-state.health);state.health=clamp(state.health+8,0,100);state.heat=clamp(state.heat-2,0,100);outcome=`You made room to rest. Wellbeing +${gain}; city attention eased a little.`;kind='good'}else if(/\b(volunteer|garden|community|help|clean up|coach|mentor|neighbor)\b/.test(prompt)){const reward=Math.min(35,180);state.cash+=reward;earnedRespect(2);state.health=clamp(state.health+3,0,100);outcome='You showed up for the neighborhood. A small stipend, respect, and a brighter day came back your way.';kind='good'}else if(/\b(work|job|gig|shift|deliver|earn)\b/.test(prompt)){const pay=55+Math.floor(Math.random()*46);state.cash+=pay;state.heat=clamp(state.heat-1,0,100);outcome=`You picked up a modest, legitimate task and earned ${money(pay)}.`;kind='good'}else if(/\b(walk|explore|visit|meet|spend time)\b/.test(prompt)){outcome='You took a low-key walk and noticed something new about the city. Choose a place from “What now?” to meet local people.';state.health=clamp(state.health+1,0,100);kind='normal'}else{outcome='You paused, named what mattered today, and made a little space to think. Wellbeing +2.';state.health=clamp(state.health+2,0,100);kind='normal'}addEvent(outcome,'kind'==='bad'?'normal':kind);endDay();result.textContent=`${outcome} This local demo uses fixed rules; it does not send your prompt to an AI service.`;render()}
function doAction(action){if(action==='work')sideHustle();if(action==='laylow')layLow();if(action==='customers'||action==='activity')chooseActivity();if(action==='influence')influence()}

